def main():
    assert len(IDS) == 60, len(IDS)
    assert set(DATA.keys()) == set(IDS), (set(IDS) ^ set(DATA.keys()))
    OUTDIR.mkdir(parents=True, exist_ok=True)
    total = 0
    counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for cid in IDS:
        pred, basis, conf, (cm, ru, di, reason) = DATA[cid]
        obj = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf,
               "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}}
        p = OUTDIR / f"{cid}.json"
        p.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
        total += p.stat().st_size
        counts["changed_main"] += cm; counts["reserve_used"] += ru; counts["disputed"] += di
    # readback verification
    written = 0
    for cid in IDS:
        obj = json.loads((OUTDIR / f"{cid}.json").read_text(encoding="utf-8"))
        assert obj["case_id"] == cid and obj["prediction_text"] and obj["basis"]
        assert 0 <= obj["confidence"] <= 1
        assert set(obj["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        assert obj["basis"].splitlines()[0].startswith("tradition:")
        written += 1
    print(f"cases={len(IDS)} written={written} total_bytes={total} trigger={counts}")

if __name__ == "__main__":
    main()
